import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder


def setup():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def state(c):
    return (balance(c, "a"), balance(c, "b"),
            c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0])


# success
c = setup(); p = Recorder()
transfer(c, p, "a", "b", 100)
assert state(c) == (0, 120, 1) and not c.in_transaction
assert p.events == [{"source": "a", "target": "b", "amount": 100}]

# invalid
for args in [("a", "a", 5), ("a", "zz", 5), ("zz", "a", 5), ("a", "b", 0), ("a", "b", -1),
             ("a", "b", True), ("a", "b", 1.0), ("a", "b", "5"), ("a", "b", 101)]:
    c = setup(); p = Recorder()
    try:
        transfer(c, p, *args)
    except ValueError:
        pass
    else:
        raise AssertionError(args)
    assert state(c) == (100, 20, 0) and p.events == [] and not c.in_transaction, args

# database failure mid-way
c = setup(); p = Recorder()
c.execute("CREATE TRIGGER t BEFORE INSERT ON ledger BEGIN SELECT RAISE(ABORT, 'boom'); END")
c.commit()
try:
    transfer(c, p, "a", "b", 10)
except sqlite3.DatabaseError:
    pass
else:
    raise AssertionError
assert state(c)[:2] == (100, 20) and p.events == [] and not c.in_transaction

# commit failure
class Conn:
    def __init__(self, c): self.c = c
    def execute(self, *a): return self.c.execute(*a)
    def commit(self): raise sqlite3.OperationalError("commit failed")
    def rollback(self): self.c.rollback()
c = setup(); p = Recorder()
try:
    transfer(Conn(c), p, "a", "b", 10)
except sqlite3.OperationalError:
    pass
else:
    raise AssertionError
assert state(c) == (100, 20, 0) and p.events == []

# publication failure keeps the commit
class Bad:
    def publish(self, e): raise RuntimeError("pub")
c = setup()
try:
    transfer(c, Bad(), "a", "b", 10)
except RuntimeError:
    pass
else:
    raise AssertionError
assert state(c) == (90, 30, 1) and not c.in_transaction
print("ok")

